import sys
sys.setrecursionlimit(300000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
        except StopIteration:
            break

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        adj = [[] for _ in range(N + 1)]
        for _ in range(N - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        if K == 1:
            total_xor = 0
            for x in A:
                total_xor ^= x
            out_lines.append(str(total_xor))
            continue

        parent = [0] * (N + 1)
        order = []
        visited = [False] * (N + 1)
        stack = [1]
        visited[1] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        subtree_xor = [0] * (N + 1)
        subtree_size = [0] * (N + 1)

        for u in reversed(order):
            val = A[u - 1]
            sz = 1
            for v in adj[u]:
                if v != parent[u]:
                    val ^= subtree_xor[v]
                    sz += subtree_size[v]
            subtree_xor[u] = val
            subtree_size[u] = sz

        total_xor = subtree_xor[1]
        ans = 0

        for bit in range(30, -1, -1):
            target_bit = 1 << bit

            if (total_xor & target_bit) == 0:
                continue

            count = 0
            temp_ans = ans | target_bit

            for u in reversed(order):
                if u == 1:
                    continue

                current_val = subtree_xor[u]
                if (current_val & temp_ans) == temp_ans:
                    count += 1

            if count >= K:
                ans = temp_ans

        out_lines.append(str(ans))

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == '__main__':
    solve()
